Index: /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/App/main.swift
===================================================================
--- /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/App/main.swift
+++ /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/App/main.swift
@@ -0,0 +1,10 @@
+import SwiftUI
+
+@main
+struct UITapApp: App {
+    var body: some Scene {
+        WindowGroup {
+            Text("UI Test Host")
+        }
+    }
+}

Index: /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/UITests/UITapTests.swift
===================================================================
--- /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/UITests/UITapTests.swift
+++ /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitap/UITests/UITapTests.swift
@@ -0,0 +1,15 @@
+import XCTest
+
+final class UITapTests: XCTestCase {
+    func testAcceptBlueskyDeepLink() {
+        let safari = XCUIApplication(bundleIdentifier: "com.apple.mobilesafari")
+        safari.activate()
+        let alert = safari.alerts.firstMatch
+        if alert.waitForExistence(timeout: 5) {
+            alert.buttons["Open"].tap()
+        }
+
+        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
+        XCTAssertTrue(bluesky.wait(for: .runningForeground, timeout: 15))
+    }
+}

